 if(argc!=3)return 1;_putenv("NF_THREADED_NO_READBACK=1");_putenv("NF_TEST_THREADED_HARDWARE_EXPORT=1");FILE*f=fopen(argv[1],"rb");if(!f)return 2;NFLayerSnapshot*snapshot=nf_layer_snapshot_create();NFHardwareLayerRow row;unsigned refresh=0;for(unsigned y=0;y<160;y++){if(fread(&row,sizeof(row),1,f)!=1||!nf_layer_snapshot_add(snapshot,&row))return 3;if(!y)refresh=row.refresh;}fclose(f);
 char*args[]={argv[0],"","","",argv[2],NULL};NFThreadedRun run={0};run.args=args;run.producer=GetCurrentThreadId();run.queue=nf_render_handoff_create(1);run.stop=CreateEvent(NULL,TRUE,FALSE,NULL);run.ready=CreateEvent(NULL,TRUE,FALSE,NULL);run.wake=CreateEvent(NULL,FALSE,FALSE,NULL);run.release=CreateEvent(NULL,TRUE,FALSE,NULL);run.inflight=CreateEvent(NULL,TRUE,FALSE,NULL);char path[1500];snprintf(path,sizeof(path),"%s-worker.csv",argv[2]);run.log=fopen(path,"wb");if(!run.log)return 4;preview_window_output=preview_keep_context=preview_measure_only=1;hud_preview=0;HANDLE worker=CreateThread(NULL,0,threaded_render,&run,0,NULL);if(!worker||WaitForSingleObject(run.ready,10000)!=WAIT_OBJECT_0)return 5;
